-- SPDX-License-Identifier: MPL-2.0
-- Arrow Player — Library database schema
-- Spec: eclipse-player.md §9.4 (REQ-LIB-001)
-- Canonical DDL; Android Room entities mirror this file exactly.
-- Migrations are numbered. Migration N must do the same thing on both
-- platforms. Do not edit this file directly — edit the spec prose first.
--
-- Current schema version: 15
-- Migration history:
--   1  → 2  : add source_id, source_path columns (REQ-LIB-020)
--   2  → 3  : add discnumber, comment, bpm columns (REQ-LIB-025)
--   3  → 4  : add composer, grouping, music_key columns
--   4  → 5  : add replaygain columns (REQ-LIB-027)
--   5  → 6  : add artwork columns (REQ-LIB-032)
--   6  → 7  : add lyrics columns
--   7  → 8  : add library_folders table
--   8  → 9  : add is_loved, is_blacklisted columns
--   9  → 10 : add play_count, skip_count, last_played_at (REQ-LIB-070)
--   10 → 11 : add albumartist_sort, artist_sort, album_sort (REQ-LIB-029)
--   11 → 12 : add cuesheets table (REQ-LIB-040)
--   12 → 13 : add cuetrack entries (REQ-LIB-042)
--   13 → 14 : add playlists sort_order column
--   14 → 15 : add sync change log table (REQ-LIB-075)

PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;
PRAGMA synchronous = NORMAL;
PRAGMA busy_timeout = 5000;
PRAGMA temp_store = MEMORY;
PRAGMA mmap_size = 268435456;  -- 256 MB

-- ===========================================================================
-- Schema version tracking
-- ===========================================================================
CREATE TABLE IF NOT EXISTS schema_version (
    version INTEGER NOT NULL PRIMARY KEY
);

-- ===========================================================================
-- Library scan roots
-- ===========================================================================
CREATE TABLE IF NOT EXISTS library_folders (
    id           INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    path         TEXT    NOT NULL UNIQUE COLLATE NOCASE,
    enabled      INTEGER NOT NULL DEFAULT 1,
    scan_state   TEXT    NOT NULL DEFAULT 'idle',  -- idle | scanning | error
    last_scan_at INTEGER,                             -- UNIX epoch ms
    created_at   INTEGER NOT NULL
);

-- ===========================================================================
-- Tracks  (REQ-LIB-001 / §9.4)
-- ===========================================================================
CREATE TABLE IF NOT EXISTS tracks (
    id                   INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    container_path       TEXT    NOT NULL UNIQUE COLLATE NOCASE,  -- absolute, canonical path
    filename             TEXT    NOT NULL,
    file_size            INTEGER NOT NULL DEFAULT 0,
    duration_ms          INTEGER NOT NULL DEFAULT 0     CHECK(duration_ms >= 0),
    -- Basic metadata (REQ-LIB-025)
    title                TEXT    NOT NULL DEFAULT '',
    artist               TEXT    NOT NULL DEFAULT '',
    album                TEXT    NOT NULL DEFAULT '',
    albumartist          TEXT    NOT NULL DEFAULT '',
    genre                TEXT    NOT NULL DEFAULT '',
    year                 INTEGER NOT NULL DEFAULT 0     CHECK(year >= 0),
    tracknumber          TEXT    NOT NULL DEFAULT '',
    discnumber           TEXT    NOT NULL DEFAULT '',
    comment             TEXT    NOT NULL DEFAULT '',
    bpm                 REAL    NOT NULL DEFAULT 0.0  CHECK(bpm >= 0.0),
    composer             TEXT    NOT NULL DEFAULT '',
    grouping             TEXT    NOT NULL DEFAULT '',
    music_key            TEXT    NOT NULL DEFAULT '',
    -- ReplayGain (REQ-LIB-027)
    rg_track_gain        REAL    NOT NULL DEFAULT 0.0,
    rg_track_peak        REAL    NOT NULL DEFAULT 0.0,
    rg_album_gain        REAL    NOT NULL DEFAULT 0.0,
    rg_album_peak        REAL    NOT NULL DEFAULT 0.0,
    -- Audio properties
    bitrate_kbps         INTEGER NOT NULL DEFAULT 0     CHECK(bitrate_kbps >= 0),
    sample_rate          INTEGER NOT NULL DEFAULT 0     CHECK(sample_rate >= 0),
    bit_depth            INTEGER NOT NULL DEFAULT 0     CHECK(bit_depth >= 0),
    channels             INTEGER NOT NULL DEFAULT 0     CHECK(channels >= 0),
    codec                TEXT    NOT NULL DEFAULT '',
    container            TEXT    NOT NULL DEFAULT '',
    is_lossless          INTEGER NOT NULL DEFAULT 0,
    -- Artwork (REQ-LIB-032)
    artwork_id           TEXT,
    has_artwork          INTEGER NOT NULL DEFAULT 0,
    -- Lyrics
    lyrics_id            TEXT,
    has_lyrics           INTEGER NOT NULL DEFAULT 0,
    -- Source / URL
    source_id            TEXT    NOT NULL DEFAULT '',
    source_path          TEXT    NOT NULL DEFAULT '',
    -- User-state (REQ-LIB-070)
    rating               INTEGER NOT NULL DEFAULT 0     CHECK(rating >= 0 AND rating <= 100),
    is_loved             INTEGER NOT NULL DEFAULT 0,
    is_blacklisted       INTEGER NOT NULL DEFAULT 0,
    play_count           INTEGER NOT NULL DEFAULT 0     CHECK(play_count >= 0),
    skip_count           INTEGER NOT NULL DEFAULT 0     CHECK(skip_count >= 0),
    last_played_at       INTEGER,                             -- UNIX epoch s
    -- Sort keys (REQ-LIB-029): NFKD-normalised, article-stripped, diacritic-free
    artist_sort_key      TEXT    NOT NULL DEFAULT '',
    album_sort_key       TEXT    NOT NULL DEFAULT '',
    -- Album identity for grouping (REQ-LIB-031)
    album_hash           TEXT    NOT NULL DEFAULT '',
    -- Cue sheet reference (REQ-LIB-040)
    cuesheet_id          TEXT,
    -- Timestamps
    added_at             INTEGER NOT NULL,
    updated_at           INTEGER NOT NULL,
    deleted_at           INTEGER,                              -- UNIX epoch s; soft delete
    -- File-identity for symlink-loop detection (§7.5 / inotify)
    file_device          INTEGER NOT NULL DEFAULT 0,
    file_inode           INTEGER NOT NULL DEFAULT 0
);

-- FTS5 index on searchable text fields
CREATE VIRTUAL TABLE IF NOT EXISTS tracks_fts USING fts5(
    title, artist, album, albumartist, genre, composer,
    content='tracks',
    content_rowid='id',
    tokenize='unicode61 remove_diacritics 1'
);

-- Trigger: keep FTS index in sync with tracks table
CREATE TRIGGER IF NOT EXISTS tracks_fts_insert
    AFTER INSERT ON tracks BEGIN
        INSERT INTO tracks_fts(rowid, title, artist, album, albumartist, genre, composer)
        VALUES (new.id, new.title, new.artist, new.album, new.albumartist, new.genre, new.composer);
    END;

CREATE TRIGGER IF NOT EXISTS tracks_fts_update
    AFTER UPDATE ON tracks BEGIN
        INSERT INTO tracks_fts(tracks_fts, rowid, title, artist, album, albumartist, genre, composer)
        VALUES ('delete', old.id, old.title, old.artist, old.album, old.albumartist, old.genre, old.composer);
        INSERT INTO tracks_fts(rowid, title, artist, album, albumartist, genre, composer)
        VALUES (new.id, new.title, new.artist, new.album, new.albumartist, new.genre, new.composer);
    END;

CREATE TRIGGER IF NOT EXISTS tracks_fts_delete
    AFTER DELETE ON tracks BEGIN
        INSERT INTO tracks_fts(tracks_fts, rowid, title, artist, album, albumartist, genre, composer)
        VALUES ('delete', old.id, old.title, old.artist, old.album, old.albumartist, old.genre, old.composer);
    END;

-- Indices
CREATE INDEX IF NOT EXISTS idx_tracks_container_path ON tracks(container_path);
CREATE INDEX IF NOT EXISTS idx_tracks_artist         ON tracks(artist);
CREATE INDEX IF NOT EXISTS idx_tracks_album          ON tracks(album);
CREATE INDEX IF NOT EXISTS idx_tracks_albumartist     ON tracks(albumartist);
CREATE INDEX IF NOT EXISTS idx_tracks_genre          ON tracks(genre);
CREATE INDEX IF NOT EXISTS idx_tracks_year           ON tracks(year);
CREATE INDEX IF NOT EXISTS idx_tracks_added_at       ON tracks(added_at);
CREATE INDEX IF NOT EXISTS idx_tracks_rating         ON tracks(rating);
CREATE INDEX IF NOT EXISTS idx_tracks_play_count      ON tracks(play_count);
CREATE INDEX IF NOT EXISTS idx_tracks_last_played    ON tracks(last_played_at);
CREATE INDEX IF NOT EXISTS idx_tracks_source_id      ON tracks(source_id) WHERE source_id != '';
CREATE INDEX IF NOT EXISTS idx_tracks_album_hash     ON tracks(album_hash) WHERE album_hash != '';
CREATE INDEX IF NOT EXISTS idx_tracks_deleted        ON tracks(deleted_at) WHERE deleted_at IS NOT NULL;
-- Compound: device+inode for symlink-loop detection
CREATE INDEX IF NOT EXISTS idx_tracks_device_inode   ON tracks(file_device, file_inode) WHERE file_device != 0;

-- ===========================================================================
-- Cue sheets  (REQ-LIB-040 .. REQ-LIB-044)
-- ===========================================================================
CREATE TABLE IF NOT EXISTS cuesheets (
    id              TEXT    NOT NULL PRIMARY KEY,   -- SHA-256 of the .cue file content
    file_path       TEXT    NOT NULL,              -- original .cue file path
    file_device     INTEGER NOT NULL DEFAULT 0,
    file_inode      INTEGER NOT NULL DEFAULT 0,
    performer       TEXT    NOT NULL DEFAULT '',
    title           TEXT    NOT NULL DEFAULT '',
    file_ref        TEXT    NOT NULL,              -- the FILE block's name
    file_is_flac    INTEGER NOT NULL DEFAULT 0,   -- true when FILE ... FLAC
    catalog         TEXT    NOT NULL DEFAULT '',
    created_at      INTEGER NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_cuesheets_file_path   ON cuesheets(file_path);

CREATE TABLE IF NOT EXISTS cuetracks (
    id              INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    cuesheet_id     TEXT    NOT NULL REFERENCES cuesheets(id) ON DELETE CASCADE,
    position        INTEGER NOT NULL DEFAULT 0,              -- 0-based index within cue
    title           TEXT    NOT NULL DEFAULT '',
    performer       TEXT    NOT NULL DEFAULT '',
    -- Time fields stored as raw sample counts or CD-DA sectors (75 frames/s).
    -- converted to ms by the caller using the referenced track's sample_rate.
    start_offset    INTEGER NOT NULL DEFAULT 0,              -- start position (frames)
    end_offset      INTEGER NOT NULL DEFAULT 0,              -- exclusive end (frames); 0 = EOF
    isrc            TEXT    NOT NULL DEFAULT '',
    flags           TEXT    NOT NULL DEFAULT ''
);

CREATE INDEX IF NOT EXISTS idx_cuetracks_cuesheet    ON cuetracks(cuesheet_id, position);

-- ===========================================================================
-- Custom / user-defined tags  (REQ-LIB-033)
-- ===========================================================================
CREATE TABLE IF NOT EXISTS track_custom_tags (
    track_id   INTEGER NOT NULL REFERENCES tracks(id)      ON DELETE CASCADE,
    key        TEXT    NOT NULL,
    value      TEXT    NOT NULL,
    updated_at INTEGER NOT NULL,
    PRIMARY KEY (track_id, key, value)
);

CREATE INDEX IF NOT EXISTS idx_track_custom_tags_key_value
    ON track_custom_tags(key, value);

-- ===========================================================================
-- Playlists
-- ===========================================================================
CREATE TABLE IF NOT EXISTS playlists (
    id          INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    uuid        TEXT    NOT NULL UNIQUE,
    name        TEXT    NOT NULL,
    description TEXT    NOT NULL DEFAULT '',
    kind        INTEGER NOT NULL,            -- 0=manual, 1=smart
    rule_json   TEXT,                        -- smart-playlist rule JSON; NULL for manual
    auto_refresh INTEGER NOT NULL DEFAULT 1,  -- re-evaluate smart playlist on scan
    sort_order  INTEGER NOT NULL DEFAULT 0,  -- user-defined position
    created_at  INTEGER NOT NULL,
    updated_at  INTEGER NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_playlists_uuid       ON playlists(uuid);
CREATE INDEX IF NOT EXISTS idx_playlists_kind      ON playlists(kind);

CREATE TABLE IF NOT EXISTS playlist_items (
    playlist_id  INTEGER NOT NULL REFERENCES playlists(id) ON DELETE CASCADE,
    position     INTEGER NOT NULL,
    track_id     INTEGER NOT NULL REFERENCES tracks(id)    ON DELETE CASCADE,
    added_at     INTEGER NOT NULL,
    PRIMARY KEY (playlist_id, position)
);

CREATE INDEX IF NOT EXISTS idx_playlist_items_track ON playlist_items(track_id);

-- ===========================================================================
-- Sync change log  (REQ-LIB-075, §18)
--
-- A full-history append-only log. Devices replay from their local clock value
-- to obtain all changes they have not yet applied. Rows are never updated or
-- deleted. The lamport_clock column provides ordering across devices: two
-- updates to the same row from different devices must be ordered, and the
-- larger clock wins (last-write-wins per §18.3).
-- ===========================================================================
CREATE TABLE IF NOT EXISTS change_log (
    id            INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    lamport_clock INTEGER NOT NULL,   -- monotonically increasing across all devices
    device_id     TEXT    NOT NULL,  -- originating device identifier
    entity_type   TEXT    NOT NULL,   -- 'track' | 'playlist' | 'playlist_item' | 'custom_tag'
    entity_id     TEXT    NOT NULL,  -- platform-specific primary key as string
    operation     TEXT    NOT NULL,  -- 'insert' | 'update' | 'delete'
    payload       TEXT    NOT NULL,  -- JSON: { "columns": { ... } } or null on delete
    applied_at    INTEGER NOT NULL   -- local UNIX epoch when this device applied the change
);

CREATE INDEX IF NOT EXISTS idx_change_log_clock   ON change_log(lamport_clock);
CREATE INDEX IF NOT EXISTS idx_change_log_entity ON change_log(entity_type, entity_id);
CREATE INDEX IF NOT EXISTS idx_change_log_applied ON change_log(applied_at) WHERE applied_at IS NULL;

-- Per-entity change indices for fast sync queries
CREATE INDEX IF NOT EXISTS idx_change_log_track    ON change_log(entity_type, lamport_clock) WHERE entity_type = 'track';
CREATE INDEX IF NOT EXISTS idx_change_log_playlist ON change_log(entity_type, lamport_clock) WHERE entity_type = 'playlist';
